"""Predicts the component p-82af68dd@100000/layers.15.mlp.down_proj:768 from hedging words.

The component's activation is large in magnitude on modal and hedging words ("if", "can",
"may", "might", "could", "would", "often", ...), and near zero elsewhere. Its sign flips
from one occurrence to the next, so the program predicts each word's average value, which
is small. Everywhere else it predicts zero. The first token of each document is zero.
"""

READS = ()

HEDGE_MEAN = {
    " if": -0.18, " can": -0.19, " may": 0.06, " might": 0.05, " could": -0.12,
    " should": 0.04, " would": -0.12, " will": 0.16, " be": -0.08, " often": 0.21,
    " sometimes": -0.06, " must": 0.08, " usually": 0.43, " possible": -0.03, " such": -0.19,
}


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return carry, 0.0
    return carry, HEDGE_MEAN.get(prefix.token_strings[-1], 0.0)

"""Layer 15 MLP down_proj, component 774.

What it does: it goes negative where the text is set up for an elaboration or a list.
Read through the unembedding, its negative direction promotes "such", "including",
"例如" and "包括", so a negative activation means "an example or a list is coming next".
The clearest case is a comma that closes a complete noun phrase in the middle of a
sentence, most strongly right after a plural noun ("...many phenomena[,] natural and
unnatural", "...substances[,] including"). A comma that closes a short sentence-opening
phrase ("Today[,] most states...") is slightly positive. An opening parenthesis, a
sentence end, a coordinating "and"/"or" and an article are mildly negative. Everything
else sits at the usual small negative level.

The program reads only the prefix: the current token, how many tokens since the last
sentence boundary, and whether the previous word looks like a plural noun. It carries
those counters across positions and resets them at each document boundary.
"""

READS = ()

COMMAS = {",", "，", "、"}
BOUNDARY = {".", "!", "?", ";", ":", "。", "！", "？"}
BASE = -0.07  # typical value of ordinary tokens
MID_COMMA = -0.4  # comma closing a clause or noun phrase mid-sentence
PLURAL_COMMA = -0.8  # same, right after a plural-looking noun
OPENING_COMMA = 0.1  # comma closing a short sentence-opening phrase
MILD = {"(": -0.3, ".": -0.2, "and": -0.14, "or": -0.14, "the": -0.17, "a": -0.17, "an": -0.17}


def looks_plural(word):
    """A plural noun, by spelling: ends in 's', is more than 3 letters and is not 'ss'."""
    return word.isalpha() and len(word) > 3 and word.endswith("s") and not word.endswith("ss")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "since": 0, "prev": ""}
    since, prev = carry["since"], carry["prev"]

    if tok in COMMAS:
        if since < 3:
            value = OPENING_COMMA
        elif looks_plural(prev):
            value = PLURAL_COMMA
        else:
            value = MID_COMMA
    else:
        value = MILD.get(tok, BASE)

    is_boundary = tok in BOUNDARY or "\n" in prefix.token_strings[-1]
    new_carry = {"doc": doc, "since": 0 if is_boundary else since + 1, "prev": tok}
    return new_carry, float(value)

"""Degree-word detector for MLP unit 787 of layer 15.

What it responds to: a word that completes a degree or quantity phrase. The unit is quiet
on most tokens. It fires on a word (adjective, adverb or noun) that directly follows a word
saying how much or how strongly, as in "very [interesting]", "extremely [challenging]",
"too [easy]", "pretty [good]", "much [interest]", "several [years]", "a huge [punch]",
"a significant [step]", "an incredible [effort]".

Rules, strongest first:
- after an intensifier (very, extremely, too, so, quite, really...): high if the word is an
  adjective ("very [interesting]"), low otherwise;
- after a quantity word (much, few, several, lot...) or a magnitude or evaluative adjective
  (huge, significant, great, important...): medium;
- after any other adjective or adverb: weak;
- a word that is itself a measure of time or amount (years, hours, miles, million) or an
  evaluative or difficulty adjective (easy, difficult, interesting...) gets a medium value
  even with no degree word before it, because these words are usually modified by one.

Why it is written this way: the activation is spread over many contexts, and the word lists
are the concept, not a fitted table. On the eval rows this program explains about 6.7% of the
variance (Pearson r 0.26); the first three rules alone explained 6.0%. A lookup table of
activation by previous and current token reaches about 8% on held-out training rows, so most
of the unit's variance is contextual and is not captured by word classes.
"""

import wordnet

READS = ()

# Words that say "how much / how strongly" and come before the word they modify.
INTENSIFIERS = {
    "very", "extremely", "quite", "pretty", "too", "so", "really", "highly", "rather",
    "fairly", "relatively", "incredibly", "particularly", "especially", "somewhat",
    "truly", "absolutely", "totally", "completely", "entirely", "fully", "greatly",
    "widely", "heavily", "slightly", "strongly", "significantly", "remarkably",
    "exceptionally", "unusually", "super",
}

# Quantity words: "few years", "several times", "much more", "a lot of".
QUANTITY = {
    "much", "many", "few", "little", "several", "lot", "lots", "bit", "most", "more",
    "numerous", "enough", "less",
}

# Magnitude and evaluative adjectives: "a huge gap", "a significant step", "great care".
MAGNITUDE = {
    "huge", "considerable", "vast", "serious", "significant", "great", "big", "large",
    "major", "wide", "broad", "powerful", "valuable", "excellent", "amazing", "nice",
    "incredible", "tremendous", "enormous", "immense", "massive", "profound", "crucial",
    "critical", "important", "high", "low", "strong", "good", "easy", "difficult", "hard",
    "interesting",
}

# Measures of time, distance and large amounts: "years", "hours", "miles", "million".
MEASURES = {
    "year", "years", "month", "months", "week", "weeks", "day", "days", "hour", "hours",
    "minute", "minutes", "second", "seconds", "mile", "miles", "million", "millions",
    "century", "centuries", "decade", "decades",
}

# Evaluative and difficulty adjectives, which are usually modified by a degree word.
EVALUATIVE = {
    "easy", "easier", "difficult", "hard", "harder", "interesting", "important", "powerful",
    "valuable", "amazing", "complicated", "challenging", "fun", "nice", "beautiful", "cool",
    "helpful", "comprehensive", "impossible", "expensive", "great", "excellent", "detailed",
}


def _word(text):
    """A token's word text, lower-cased and stripped of its leading space."""
    return text.strip().lower()


def _is_word(text):
    """True for a token that is a whole alphabetic word (not punctuation or a fragment)."""
    return text.startswith(" ") and text.strip().isalpha()


def _is_adjective(text):
    return "adjective" in wordnet.parts_of_speech(_word(text))


def _is_adjective_or_adverb(text):
    parts = wordnet.parts_of_speech(_word(text))
    return "adjective" in parts or "adverb" in parts


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    cur, prev = prefix.token_strings[-1], prefix.token_strings[-2]
    if not _is_word(cur):
        return carry, 0.0
    before, word = _word(prev), _word(cur)
    value = 0.0
    if before in INTENSIFIERS:
        value = 4.7 if _is_adjective(cur) else 0.6
    elif before in QUANTITY or before in MAGNITUDE:
        value = 2.5
    elif _is_adjective_or_adverb(prev):
        value = 0.4
    if word in MEASURES:
        value = max(value, 2.0)
    if word in EVALUATIVE:
        value = max(value, 3.0)
    return carry, value

"""Chinese action verbs: a small positive activation on a single-character or
two-character Chinese verb token, where the dictionary gloss starts with 'to'."""
import cedict
import regex

READS = ()
VERB_LEVEL = 0.15


def is_verb(token):
    if not regex.fullmatch(r"\p{Han}{1,3}", token):
        return False
    glosses = cedict.glosses(token) or ()
    return bool(glosses) and glosses[0].startswith("to ")


def step(carry, prefix, upstream):
    return carry, VERB_LEVEL if is_verb(prefix.token_strings[-1]) else 0.0

"""Predicts layers.15.mlp.down_proj:790 from the surface form of the current token.

This component is a small, diffuse direction in layer 15's MLP output. Its activation
has mean about -0.03 and spread about 0.38, but almost none of that spread follows
the token itself. What a short program can read is a few coarse token-class averages:

- a document's first token: about 0 (the activation hardly varies there);
- a bare newline (whitespace containing a line break): about +0.05;
- a digit token ("1", "23"): about -0.05;
- a spaced English word (" the", " of", " used"): about -0.04;
- anything else (punctuation, unspaced word pieces, code, other scripts): about -0.01.

These averages explain only about 0.2% of the variance on training text. Most of the
variance depends on longer context (the lag-1 autocorrelation is 0.4, and the average
over the whole document explains about 7%), which this program does not model.
"""
import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

DIGITS = re.compile(r"\d+")
SPACED_WORD = re.compile(r" [A-Za-z]+")


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    first_in_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first_in_doc:
        value = 0.0
    elif "\n" in tok and not tok.strip():
        value = 0.05
    elif DIGITS.fullmatch(tok):
        value = -0.05
    elif SPACED_WORD.fullmatch(tok):
        value = -0.04
    else:
        value = -0.01
    return carry, value

"""Layer-15 MLP unit 791 (down_proj component 791), a near-noise feature.

Its activation is a weighted sum of the layer-15 MLP hidden units, mostly unit 791, and no
simple concept predicts it well: rare large excursions of both signs are spread over many
kinds of token. What is stable is small: near zero at each document's first token, and a
small class-dependent mean elsewhere (larger after spaces and before punctuation, smaller
for digits and for word pieces that do not begin with a space).
"""

READS = ()

CLASS_MEAN = {
    "bytes": 0.002,      # partial UTF-8 character
    "digit": 0.008,      # digits
    "piece": 0.013,      # word piece with no leading space
    "newline": 0.029,
    "Capital": 0.036,    # space + capitalised word
    "word": 0.044,       # space + lowercase word
    "symbol": 0.047,     # punctuation and other symbols
}


def token_class(text):
    if not text or "�" in text:
        return "bytes"
    if text[0].isdigit():
        return "digit"
    if text[0] == "\n":
        return "newline"
    if text[0] == " ":
        body = text[1:]
        if not body:
            return "symbol"
        if body[0].isupper():
            return "Capital"
        return "word" if body[0].isalpha() else "symbol"
    if text[0].isalpha():
        return "piece"
    return "symbol"


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    if len(ids) < 2 or ids[-1] != ids[-2]:
        return carry, 0.0
    return carry, CLASS_MEAN[token_class(prefix.token_strings[-1])]

"""Layer 15 MLP hidden unit 796, as read through this component's down_proj direction.

The component's activation is almost entirely MLP hidden unit 796 of layer 15 (its read
vector is 0.85 on that unit and small elsewhere). Unit 796 is a "a number comes next"
detector for reference labels, and it also marks chat-template openings and a few web-page
boilerplate words. It is high on the token just before a figure, table, section or question
number ("Figure [ ]3", "Table[ ]4", "Fig.[ ]1", "Question[ ]7"), on the role name
"assistant" after "<|im_start|>", on the blank line after "<think>", and on a numbered list
item after a blank line. Elsewhere it is near zero, with noise this program does not capture.

The program is a short list of such rules. It sees only the tokens so far.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Words that name a figure or table: a number follows them after a space.
FIGURE_WORDS = {"Figure", "Fig", "FIG", "Figures", "Table", "TABLE"}
# Other labels that a number follows: question, section, equation, step, and so on.
LABEL_WORDS = {
    "Question", "Section", "section", "sec", "Eq", "Theorem", "Lemma", "Step",
    "Example", "Exercise", "Problem", "Chapter", "Part", "Page", "Vol", "No", "Article",
}  # fmt: skip
# Web-page words (post counts, tags, "Joined", "permalink") that mark forum boilerplate.
FORUM_WORDS = {"Posted", "Joined", "Posts", "Tags", "udos", "permalink", "views"}


def step(carry, prefix, upstream: Mapping):
    """This token's activation, from the current token and the one before it."""
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    word = prev.strip()
    if cur == "assistant" and prev == "<|im_start|>":
        value = 9.0  # the role name that opens an assistant turn
    elif cur == "\n\n" and prev == "<think>":
        value = 12.0  # the blank line after an opening think tag
    elif cur == " " and word in FIGURE_WORDS:
        value = 11.0  # the space before a figure or table number
    elif cur == "." and word in {"Fig", "FIG"}:
        value = 5.7  # the period of "Fig." before its number
    elif cur == " " and word in LABEL_WORDS:
        value = 3.0  # the space before any other label's number
    elif cur.isdigit() and prev == ":\n\n":
        value = 3.5  # a number starting a list item
    elif cur == "." and word == "al":
        value = 2.8  # "et al." before a citation year
    elif cur in FORUM_WORDS:
        value = 5.0  # web-page boilerplate
    elif cur == "\n\n" and prev == "</think>":
        value = 4.8  # the blank line after a closing think tag
    elif cur == "\n" and prev == "<|im_end|>":
        value = 1.5  # the newline after the end of a chat turn
    else:
        value = 0.0
    return carry, value

"""Layer 15, MLP hidden unit 803 (the component is this unit's value times about 1.6).

Plain-terms summary: this unit is diffuse. Its value is signed and no simple token or
word-class rule explains it: the token identity explains about 3% of its variance and
concept-level rules under 1%. The one consistent pattern is on articles ("the", "a", "an"):
after some words the unit leans positive, after others negative. At the first token of a
document it is silent.

This program predicts 0 everywhere except on an article, where it predicts the sign the
data shows for the word just before it.
"""

READS = ()

ARTICLES = {"the", "a", "an"}
# Words before an article after which the value tends to be positive (about +0.4 to +0.9).
LEANS_POSITIVE = {
    "of", "in", "is", "as", "by", "into", "through", "are", "was", "be", "has", "have",
    "on", "from", "using", "make", "such",
}
# Words before an article after which the value tends to be negative (about -0.2 to -1.0).
LEANS_NEGATIVE = {
    "to", "for", "at", "under", "about", "and", "that", "with", "all", "find", "get", "within",
}


def step(carry, prefix, upstream):
    # The first token of a document: silent.
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    word = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip()
    if word not in ARTICLES:
        return carry, 0.0
    if before in LEANS_POSITIVE:
        return carry, 0.5
    if before in LEANS_NEGATIVE:
        return carry, -0.4
    return carry, 0.0

"""Component L15 MLP down_proj #809: an "introducing an example" detector, written negative.

The component's activation is near zero on most tokens. It goes strongly negative on the
word or symbol that opens an illustration: the "example" in "For example,", the "e.g" in
"(e.g., ...)", the "such" in "such as", "like", "including", "namely", the foreign-language
equivalents ("例如", "например", "par exemple", ...), and, more weakly, on the colon or
paragraph break that introduces a list. Sentence ends are only slightly negative.

This program reads only the newest two tokens and returns a fixed value per cue class,
with weights fitted by least squares to the component's activations. It does not model the
diffuse positive and mid-range variation that carries most of the remaining variance.
"""

READS = ()

EXAMPLE_WORDS = {" example", " examples", " Example", "example", " instance", " Instance", " instances"}
FOR_WORDS = {" For", "For", " for", "for"}
ABBREVIATION_TAILS = {".g", ".e", ".eg", ".B", ".,"}
ABBREVIATION_HEADS = {"e", "i", "z", "e.g", "i.e", ".g", ".e"}
SUCH_LIKE = {" such", "such", " like", "like", " Like", " including", " include", " includes", "including", " namely", " especially"}
FOREIGN_CUES = {"例如", "比如", "比如说", "例", "имер", "Например", "ejemplo", "exemple", "напр", "caso", " tel", " Por", " Par"}
COLON_BREAKS = {":\n\n", ":\n\n\n", "：\n\n", ":\n", ":\n "}
PARAGRAPH_ENDS = {".\n\n", "?\n\n", ".\n"}
SENTENCE_ENDS = {".", "?"}


def cue_value(token, previous):
    """The activation this cue class gives, from the newest token and the one before it."""
    if token in EXAMPLE_WORDS:
        return -6.4 if previous in FOR_WORDS else -0.5  # "For example" vs "an example"
    if token in ABBREVIATION_TAILS and previous in ABBREVIATION_HEADS:
        return -2.7  # "e.g.", "i.e."
    if token == " as" and previous == " such":
        return -2.3  # "such as"
    if token in SUCH_LIKE:
        return -1.1
    if token in FOREIGN_CUES:
        return -1.9
    if token in COLON_BREAKS:
        return -0.9  # a colon or break that opens a list
    if token in PARAGRAPH_ENDS:
        return -0.4
    if token in SENTENCE_ENDS:
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    tokens, docs = prefix.token_strings, prefix.document_ids
    newest = len(tokens) - 1
    # The token before the newest one counts only within the same document.
    previous = tokens[newest - 1] if newest >= 1 and docs[newest - 1] == docs[newest] else ""
    return carry, cue_value(tokens[newest], previous)

"""Predicts layers.15.mlp.down_proj component 812, a single neuron-like feature of layer 15's MLP.

Plain-terms summary of what it responds to (fit on ~16k training rows):
- A finite "be"/"have" verb right after a noun phrase, where a predicate agreeing with that
  noun is due next: "the results are", "the temperature was", "the time has". Strongly positive.
- The same verbs right after a pronoun or conjunction: "it is", "he was", "and was". Mildly negative.
- Japanese and Korean case or topic particles (を が は も の 을 를 이 가 은 는 ...), which mark
  the role of a noun phrase. Strongly positive.
- Modal verbs (will, can, would ...) and "be"/"been"/"being" sit near the mean; "be" is slightly negative.
- Everything else sits near the mean, about -0.07, with no clear rule.

This captures only about 4% of the variance. Most of it is diffuse, context-dependent noise
that no short rule describes. A token lookup table would reach about 7%, but it has no concept behind it.
"""

from collections.abc import Mapping

import wordnet

READS: tuple[str, ...] = ()

# Pronouns and conjunctions: a verb after one of these is not agreeing with a noun subject.
PRONOUNS = {
    "it", "he", "she", "they", "we", "i", "you", "who", "that", "which", "this", "these",
    "those", "what", "there", "and", "but", "or", "as",
}
FINITE = {"is", "are", "was", "were", "has", "have", "had"}
MODALS = {"will", "would", "can", "could", "may", "might", "must", "shall", "should"}
BE = {"be", "been", "being"}
# Japanese and Korean case and topic particles.
PARTICLES = {
    "を", "が", "は", "も", "の", "に", "で", "と", "から", "には", "では", "でも",
    "이", "가", "을", "를", "은", "는", "의", "에", "도", "에서",
}
MEAN = -0.07


def _word(text: str) -> str:
    return text.strip().lower()


def _is_noun(word: str) -> bool:
    return word.isalpha() and "noun" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1].strip()
    word = _word(prefix.token_strings[-1])
    same_document = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = _word(prefix.token_strings[-2]) if same_document else ""

    if token in PARTICLES:
        return carry, 1.3
    if word in FINITE:
        if previous in PRONOUNS:
            return carry, -0.2
        if _is_noun(previous):
            return carry, 0.7
        return carry, 0.15
    if word in MODALS:
        return carry, 0.1
    if word in BE:
        return carry, -0.18
    return carry, MEAN

"""Predicts layer 15 MLP unit 820 (component p-82af68dd ... down_proj:820).

The component is one hidden unit of layer 15's MLP, written into the residual stream along
its down-projection column, so its activation is that unit's value times the column's norm.
That value is noisy and depends on context a token list cannot describe, so this program
only predicts the broad token-class pattern in it:

- a document's first token: about 0;
- line layout (newlines, tabs, indentation): the most negative and most variable;
- punctuation and other symbols: negative;
- ordinary words with a leading space: the least negative.

Its class means are the averages measured on training rows. It uses only the newest token.
"""

import re

READS = ()

# Mean activation of each token class, measured on training rows.
MEAN = {"layout": -0.122, "word": -0.049, "punct": -0.100, "other": -0.099}

WORD = re.compile(r" ?[A-Za-z]+")
PUNCT = re.compile(r"[^\w\s]+")
SPACE = re.compile(r"\s+")


def token_class(text):
    """The class of one token's text, decoded alone."""
    if "\n" in text or "\t" in text or SPACE.fullmatch(text):
        return "layout"
    if WORD.fullmatch(text):
        return "word"
    if PUNCT.fullmatch(text):
        return "punct"
    return "other"


def step(carry, prefix, upstream):
    """The activation at the newest position: 0 at a document's first token, otherwise its class mean."""
    first = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        return carry, 0.0
    return carry, MEAN[token_class(prefix.token_strings[-1])]

"""Partitive "of": a negative detector for the preposition "of" (and its
foreign equivalents de / di / del / des / du / van / von / der) that links a
noun to its complement.

Activation on " of" is strongly negative (about -3 on average). It is most
negative after quantity and part words ("many of", "some of", "portion of",
"majority of", "number of", "snippet of"), which introduce a part of a whole,
and weakest after idiomatic uses ("instance of", "out of", "because of",
"instead of", "consist of"). The foreign equivalents are negative too, about
-1. Everywhere else the component is near zero, so the program predicts 0.
"""

READS = ()

OF_WORDS = {" of", " Of", " OF"}
FOREIGN_OF = {" de", " di", " del", " des", " du", " van", " von", " der"}
QUANTITY_WORDS = {
    " few", " none", " several", " some", " Some", " many", " most", " Most",
    " all", " each", " Each", " any", " half", " portion", " portions",
    " majority", " fraction", " percentage", " percent", " proportion",
    " rest", " remainder", " subset", " number", " amount", " part", " parts",
    " snippet", " sum", " bulk", " pieces", " pairs", " scope",
}
IDIOM_WORDS = {
    " instance", " out", " instead", " because", " capable", " think",
    " care", " consist", " consisting", " consisted", " is", " are", " be",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in OF_WORDS:
        before = prefix.token_strings[-2] if len(prefix.token_ids) > 1 else ""
        if before in QUANTITY_WORDS:
            return carry, -4.8
        if before in IDIOM_WORDS:
            return carry, -1.0
        return carry, -3.0
    if token in FOREIGN_OF:
        return carry, -1.0
    return carry, 0.0

"""A subject pronoun, and the auxiliary or modal that follows it, in a statement.

Component p-82af68dd@100000/layers.15.mlp.down_proj:827 is most active where the model
is in the middle of a statement whose subject is a pronoun, and the next word is
likely a verb or a modal:
  - on the subject itself: "we" (strongest), "you", then "there", "I", "they", "he", "it";
  - on a modal or auxiliary right after "we", "you" or "there": "we [can]", "you [will]",
    "there [are]", "we [have]";
  - the subject is stronger after a word that opens a clause ("that", "because",
    "since", "so", "then"), and much weaker after "thank you", "with you" or "to you";
  - an auxiliary after a relative word ("who are", "that have") is switched off.
Most of the variance is in these spikes, which a reader can see in the text.

The program looks only at the current token and the one before it (same document).
"""

READS = ()

WE = {"we", "We", "us"}
YOU = {"you", "You"}
THERE = {"there", "There"}
I_PRONOUN = {"I"}
OTHER = {"they", "They", "he", "He", "she", "She", "it", "It"}
SUBJECT = WE | YOU | THERE | I_PRONOUN | OTHER | {"one", "One", "man", "on"}
STRONG_SUBJECT = WE | YOU | THERE
AUX = {
    "will", "would", "can", "may", "could", "should", "might", "must", "shall", "have",
    "has", "had", "need", "cannot", "won", "don", "Will", "Can", "Would", "Should", "Must",
    "Have", "Need", "'ll", "’ll", "'re", "’re", "'ve", "’ve", "is", "are", "be", "was",
    "were", "get",
}
RELATIVE = {"who", "that", "which", "whom", "whose"}
CLAUSE_OPENERS = {
    "that", "because", "since", "so", "then", "where", "now", "sure", "but", "and", "think",
    "know", "means", "say", "believe", "hope", "Since", "Because", "So", "Then", "Now", "That",
}
AFTER_THANKS = {"Thank", "thank", "with", "to", "of", "from", "about", "help", "assist"}


def _word(s):
    return s.strip()


def step(carry, prefix, upstream):
    cur = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""

    value = 0.0
    if cur in WE:
        value = 3.8
    elif cur in YOU:
        value = 3.4
    elif cur in THERE or cur in I_PRONOUN:
        value = 1.2
    elif cur in OTHER:
        value = 0.7
    elif cur in AUX:
        value = 0.1

    if cur in AUX:
        if prev in STRONG_SUBJECT:
            value += 3.0
        elif prev in SUBJECT:
            value += 0.5
        elif prev in RELATIVE:
            value -= 0.35

    if prev in SUBJECT:
        value += 0.3

    if cur in SUBJECT:
        if prev in CLAUSE_OPENERS:
            value += 1.5
        elif prev in AFTER_THANKS:
            value -= 1.25

    return carry, float(value)
